input double StopLossPips = 100;         // Stop Loss em Pips (Note: SL/TP calculation needs refinement, see notes below)
input int slippage = 3;                  // Slippage permitido

//+------------------------------------------------------------------+
//| Função para calcular a EMA (Reads the indicator value)        |
//+------------------------------------------------------------------+
double CalculateEMA(int period, int shift)
{
   // iMA returns the value of the specified MA on the specified bar (shift)
   return iMA(NULL, 0, period, 0, MODE_EMA, PRICE_CLOSE, shift);
}

//+------------------------------------------------------------------+
//| Verifica condições de compra                                     |
//+------------------------------------------------------------------+
